Method.Implementation:
/*
if ($get(%session.Data("PsWd")) = "")
{
	&js<alert('Server Method, login required');>
	Quit $$$ERROR($$$EnsErrGeneral, "Please login")		
}
*/

return $$$OK

 Do %page.%SetValueById("namespLbl","ITFCOMMON")
 Do %page.%SetValueById("userLbl",$USERNAME)
 Do %page.%SetValueById("systemLbl", $SYSTEM)
 Do %page.%SetValueById("stDtTm", $ZDATETIME($PIECE($HOROLOG,",",1)_",0",3,1,2))
 Do %page.%SetValueById("endDtTm", $ZDATETIME($PIECE($HOROLOG,",",1)_",86399", 3,1,2))
  try {
	Set img = %page.%GetComponentById("TemplateLogo")
    Set stream=##class(%FileBinaryStream).%New()

    if $$$ISOK(stream.LinkToFile("/WORK/common/images/intermountain.jpg"))
    {
     Set oid=stream.%Oid()
     Set img.streamId = oid 
   }
 } catch err
 {
 }
 return $$$OK

var srcFields = zenPage.getComponentById('srcFields').getValue();

sessionGrp = zenPage.getComponentById('sessionRange');
dtGrp = zenPage.getComponentById('dtRange');
if(srcFields == "Date")
{
	sessionGrp.setProperty('hidden', true);
	dtGrp.setProperty('hidden', false);
}
else
{
	sessionGrp.setProperty('hidden', false);
	dtGrp.setProperty('hidden', true);

}

   var nmSp = zenPage.getComponentById('namespace').getValue();

	   	var srcComponent = zenPage.getComponentById('srcComponent').getValue();
	    var destComponent = zenPage.getComponentById('destComponent').getValue();


	    var dtSearch = zenPage.getComponentById('srcFields').getValue();
	    var maxRows = zenPage.getComponentById('msgCnt').getValue();


	    var recCnt = isNaN(parseInt(maxRows)) ? -1 : maxRows;

	    if( dtSearch == "Date")
	    {
	    	var rangeVal1 = zenPage.getComponentById('stDtTm').getValue();
	    	var rangeVal2 = zenPage.getComponentById('endDtTm').getValue();
	    }
	    else
	    {
		   	var rangeVal1 = zenPage.getComponentById('stSessionId').getValue();
	    	var rangeVal2 = zenPage.getComponentById('endSessionId').getValue();

	    }
	    if(nmSp == '' || srcComponent == '' || destComponent == '' || rangeVal1 == '' || rangeVal2 == '')
	    {

			    var missingFlds = 'Required fields are missing' 
			    if(nmSp == '')
			     missingFlds = missingFlds + " Namespace " 
			     if( srcComponent == '' ) missingFlds  = missingFlds + ', Source '
			     if( destComponent == '' ) missingFlds =  missingFlds + ', Destination '

			     if( rangeVal1 == '' ) missingFlds =  missingFlds + ', Date or SessionId Starting value '
			     if( rangeVal2 == '') missingFlds =  missingFlds + ', Date or SessionId Ending value '
			     zenPage.getComponentById('lblAccess').setValue(missingFlds )
		}
		else
		{

			zenPage.getComponentById('lblAccess').setValue('Getting Records');

		    try
		    {	
		    	timerVar = setInterval(function(){ zenPage.VerifyTimer('Getting Records')}, 1000);
  		   		zenPage.refreshContents(true); 
		    	var statStr = zenPage.GetRecs(nmSp, srcComponent, destComponent,  dtSearch, rangeVal1, rangeVal2, recCnt)

		    	zenPage.getComponentById('lblAccess').setValue(statStr);
		    	return;


		    } catch(err)
		    {
			    zenPage.getComponentById('lblAccess').setValue('Exception in getRecords: ' + err.message);
		    }
		}

 try {
	 set $NAMESPACE = nmSp
	 set retStr = ""

 	set sesId = %page.%GetValueById("sesId")
    set createTm = %page.%GetValueById("createTm")
    set msgBodyId = %page.%GetValueById("msgBodyId")

 	 set msgType = 	%page.%GetValueById("msgType")

	 SET myquery = 5 


	 IF ((msgType = "HL7") || (msgType = 1)) {
		SET myquery(1) = " select SessionId, mh.TimeCreated, MessageBodyId, RawContent as Data "
	 	SET myquery(2) = " from  Ens.MessageHeader mh, EnsLib_HL7.Message msg "
	 	SET myquery(3) = " where mh.MessageBodyId = msg.ID and MessageBodyClassName = 'EnsLib.HL7.Message' "
	  }
	  ELSEIF ((msgType = "XML") || (msgType = 2)) {
    	SET myquery(1) = " select SessionId, mh.TimeCreated, MessageBodyId, RawContent as Data "
	 	SET myquery(2) = " from  Ens.MessageHeader mh, EnsLib_EDI_XML.Document msg "
	 	SET myquery(3) = " where mh.MessageBodyId = msg.ID  "
	  }
	   ELSEIF ((msgType = "X12" ) || ( msgType = 3)) {
    	SET myquery(1) = " select SessionId, mh.TimeCreated, MessageBodyId, StringValue as Data "
	 	SET myquery(2) = " from  Ens.MessageHeader mh, ENSLIB_EDI_X12.Document msg "
	 	SET myquery(3) = " where mh.MessageBodyId = msg.ID  and MessageBodyClassName = 'ENSLIB.EDI.X12.DOCUMENT' "
	  }
	   ELSEIF ((msgType = "StringContainer" ) || ( msgType = 4)) {
    	SET myquery(1) = " select SessionId, mh.TimeCreated, MessageBodyId, StringValue as Data "
	 	SET myquery(2) = " from  Ens.MessageHeader mh, Ens.StringContainer msg "
	 	SET myquery(3) = " where mh.MessageBodyId = msg.ID  and MessageBodyClassName = 'Ens.StringContainer' "
	  }
	   ELSEIF ((msgType = "StringRequest" ) || (msgType = 5)) {
    	SET myquery(1) = " select SessionId, mh.TimeCreated, MessageBodyId, StringValue as Data "
	 	SET myquery(2) = " from  Ens.MessageHeader mh, ENS.STRINGREQUEST msg "
	 	SET myquery(3) = " where mh.MessageBodyId = msg.ID  and MessageBodyClassName = 'ENS.STRINGREQUEST' "
	  }
	   ELSEIF ((msgType = "StringResponse") || (msgType = 6)) {
    	SET myquery(1) = " select SessionId, mh.TimeCreated, MessageBodyId, StringValue as Data "
	 	SET myquery(2) = " from  Ens.MessageHeader mh, ENS.STRINGRESPONSE msg  "
	 	SET myquery(3) = " where mh.MessageBodyId = msg.ID  and MessageBodyClassName = 'ENS.STRINGRESPONSE' "
	  }
	  ELSEIF ((msgType = "StreamContainer GC" ) || ( msgType = 7)) {
    	SET myquery(1) = " select SessionId, mh.TimeCreated, MessageBodyId, SUBSTRING(%OBJECT(StreamGC),0,999) as Data "
	 	SET myquery(2) = " from  Ens.MessageHeader mh, Ens.STREAMCONTAINER msg "
	 	SET myquery(3) = " where mh.MessageBodyId = msg.ID and MessageBodyClassName = 'ENS.STREAMCONTAINER' "
	  }
	  ELSEIF ((msgType = "StreamContainer FC" ) || ( msgType = 8)) {
    	SET myquery(1) = " select SessionId, mh.TimeCreated, MessageBodyId, SUBSTRING(%OBJECT(StreamFC),0,999) as Data "
	 	SET myquery(2) = " from  Ens.MessageHeader mh, Ens.STREAMCONTAINER msg "
	 	SET myquery(3) = " where mh.MessageBodyId = msg.ID and MessageBodyClassName = 'ENS.STREAMCONTAINER' "
	  }
	  ELSEIF ((msgType = "StreamContainer CG" ) || ( msgType = 9)) {
    	SET myquery(1) = " select SessionId, mh.TimeCreated, MessageBodyId, SUBSTRING(%OBJECT(StreamCG),0,999) as Data "
	 	SET myquery(2) = " from  Ens.MessageHeader mh, Ens.STREAMCONTAINER msg "
	 	SET myquery(3) = " where mh.MessageBodyId = msg.ID and MessageBodyClassName = 'ENS.STREAMCONTAINER' "
	  }
	  ELSEIF ((msgType = "StreamContainer CF" ) || ( msgType = 10)) {
    	SET myquery(1) = " select SessionId, mh.TimeCreated, MessageBodyId, SUBSTRING(%OBJECT(StreamCF),0,999) as Data "
	 	SET myquery(2) = " from  Ens.MessageHeader mh, Ens.STREAMCONTAINER msg "
	 	SET myquery(3) = " where mh.MessageBodyId = msg.ID and MessageBodyClassName = 'ENS.STREAMCONTAINER' "
	  }


	  ELSE
	  {
		  set retStr = "Invalid message type: " _ msgType
		  return retStr
	  }


 	 SET myquery(4) = " and SourceConfigName = ? and TargetConfigName = ? " // Type = 'Request' - 1

	 if (dtSearch = "Date")
	 {
	 	SET myquery(5) = " and mh.TimeCreated BETWEEN ? AND ? "

	 	SET zonesave= $SYSTEM.SYS.TimeZone()
	 	set $ZTIMEZONE = 0
		set h1 = $ZDATETIMEH(rangeVal1, 3, 1)
		set h2 = $ZDATETIMEH(rangeVal2, 3, 1)
		//Data is stored in DB as GMT
	 	set $ZTIMEZONE = zonesave
	 	set hDtTm1 = $SYSTEM.Util.LocalWithZTIMEZONEtoUTC(h1)
	 	set hDtTm2 = $SYSTEM.Util.LocalWithZTIMEZONEtoUTC(h2)

	 	set val1 =	$ZDATETIME(hDtTm1, 3, 1)
	 	set val2 = $ZDATETIME(hDtTm2, 3, 1)
	 	/*
	 	set val1 = rangeVal1
		set val2 = rangeVal2
		*/
	 }
	 else
	 {
 	 	SET myquery(5)  = " and mh.SessionId BETWEEN ? AND ?"
 	 	set val1 = rangeVal1
		set val2 = rangeVal2 	
	 }


  SET tStatement = ##class(%SQL.Statement).%New()
  SET qStatus = tStatement.%Prepare(.myquery)
  IF qStatus'=1 {
	    set retStr =  "%Prepare failed:" DO $System.Status.DisplayError(qStatus) 
	    return retStr _ qStatus
	 }
 set retStr = "Execute " _ srcComp _ ", " _ destComp _ ", " _ val1 _ ", " _ val2 _ ", Max rows: " _ recCnt

  SET rset = tStatement.%Execute(srcComp, destComp, val1, val2)
  IF rset.%SQLCODE=0 { set retStr =  "<BR> Executed a query successfully: <I> Source: " _ srcComp_", Destination: " _  destComp_", Range: " _  rangeVal1 _", " _  rangeVal2 _ ", Type: " _ msgType _ "</I>"}
  ELSEIF rset.%SQLCODE=-361 { $$$LOGERROR("Query exists: " _ rset.%Message) }
  ELSE { set retStr =  retStr _ ", CREATE QUERY error: " _ rset.%SQLCODE_", "_rset.%Message   return retStr}

  set arrInd = 0
  Set tMsgIdArr = ""
  Do ##class(%File).CreateDirectoryChain( "/itf-share/itf-tmp/tmp-extracts/" _ $USERNAME)
  set fileNm = $ZSTRIP("/itf-share/itf-tmp/tmp-extracts/" _ $USERNAME _ "/" _ srcComp_"_" _  destComp _ "_" _ $ZDATETIME($ZTIMESTAMP,8,1,2) _ ".txt", "*W")

  Set file=##class(%File).%New(fileNm)

	Do file.Open("WSN")

   WHILE rset.%Next() {
	 set arrInd = arrInd + 1

     if ((recCnt = -1) || (arrInd <= recCnt))
     {
	     if (sesId = "1")
	     {
		     Do file.Write( rset.SessionId _ ", ")
	     }
	     if (createTm = "1")
	     {
		     Do file.Write( rset.TimeCreated _ ", ")
	     }
	     if (msgBodyId = "1")
	     {
		     Do file.Write( rset.MessageBodyId _ ", ")
	     }
	     Do file.WriteLine(rset.Data)
     }
     else
     {
        quit	
     }
   }
   SET sc=rset.Close()

   if (arrInd > 0)
   {
   	Set retStr =  retStr _ "<BR><BR> <B>Wrote " _ arrInd _ " messages to </B>" _ fileNm _ ", size: " _ file.Size 
   }
   else
   {
	   Set retStr =  retStr _ "<BR><BR> <B> Zero records found " _ myquery(1) _ myquery(2) _ myquery(3) _ myquery(4) _ myquery(5) _ "</B>"
   }
   Do file.Close() 	

   } catch(exp)
	    {
		    set retStr = retStr _ " Exception: " _ exp.Name _", " _ exp.Code _ ", " _ exp.Data

	    }
	return retStr


	var val =  zenPage.getComponentById('namespace').getValue();
	zenPage.getComponentById('namespLbl').setValue(val);
	var compType =  zenPage.getComponentById('srcCompType').getValue();
	zenPage.getComponentById('srcComponent').resetOptions();

    var comps = zenPage.getComponents(val, compType)
    entries = comps.split(",");
    for (i=0; i<entries.length; i++)
	{
   	  zenPage.getComponentById('srcComponent').appendOption(entries[i], entries[i]);
	}

	zenPage.getComponentById('fldSetSrcComponents').setProperty('legend', 'Source: # of Components: ' + entries.length);

	var compType =  zenPage.getComponentById('destCompType').getValue();

	zenPage.getComponentById('destComponent').resetOptions();

    var comps = zenPage.getComponents(val, compType)
    entries = comps.split(",");
    for (i=0; i<entries.length; i++)
	{
   	  zenPage.getComponentById('destComponent').appendOption(entries[i], entries[i]);
	}

	zenPage.getComponentById('fldSetDestComponents').setProperty('legend', 'Destination: # of Components: ' + entries.length);

	set tSC = $$$OK
	set %session.Data("NmSp") = nmSp
	Set $NAMESPACE = nmSp
	set cmps = ""
	Set tProductionName = ##class(Ens.Director).GetActiveProductionName()

   		// $$$LOGINFO( "GetComponents " _ $NAMESPACE _ ", getProductionItems: " _ tProductionName)

   		Set tProduction = ##class(Ens.Config.Production).%OpenId(tProductionName,,.tStatus)


   		Set tStatus = ##class(Ens.Director).getProductionItems(tProduction,.tProductionDefinition)

   		If ($DATA(tProductionDefinition) = 10) {
	   		Set tConfigName = ""
			For { 
				Set tConfigName = $ORDER(tProductionDefinition(tConfigName))
				Quit:(tConfigName = "")
				Set tConfigBusinessType = tProductionDefinition(tConfigName,"BusinessType")
				Set tConfigBusinessType = $CASE(tConfigBusinessType,
              							1:"Service",
              							2:"Process",
              							3:"Operation",
              							:"Unknown")
				if ( tConfigBusinessType = compType)
				{				
					set cmps = cmps _ "," _ tConfigName
				}

			}
   		}
   		return cmps

   try
	    {
		    if( zenPage.getComponentById('lblAccess').getValue().substr(0, srcTxt.length)  != srcTxt)
  			{
	  			clearInterval(timerVar);  

   				zenSynchronousMode = true;   			  				 
  			}
  			else
  			{
	  			zenPage.getComponentById('lblAccess').setValue(zenPage.getComponentById('lblAccess').getValue() + ".");
	  			zenPage.refreshContents(true); 
  			}


} catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception in VerifyTimer: ' + err.message);
		    clearInterval(timerVar);
		    zenSynchronousMode = true;
	    }
